      SUBROUTINE DFOL3CC     DERIVATIVE OF THIRD-ORDER TRANSFER MATRIX ELEMENTS WITH C     RESPECT TO MAGNET LENGTHCC ----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM5C.CIN'      INCLUDE 'R.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESC      INTEGER         JO, KLM      REAL            DCS, DCSO, DSN, DSNO, LVC-----------------------------------------------------------------------C      J = JQUAD      LV = LVE      JO = 4 - J      CS = R(J,J)      SN = R(J,J+1)      CSO = R(JO,JO)      SNO = R(JO,JO+1)      DCS = RV(J,J)      DSN = RV(J,J+1)      DCSO = RV(JO,JO)      DSNO = RV(JO,JO+1)C      IF (J .EQ. 1) KLM = 1      IF (J .EQ. 3) KLM = 10      UV(J,KLM) = KQ2**2*(13.*DCS*SN**2 + 26.*CS*SN*DSN     1          - 9*LV*SN - 9.*L*DSN)/48.      UV(J+1,KLM) = - KQ2**2*(7.*DSN + 45.*KQ2*SN**2*DSN     1            + 9.*LV*CS + 9.*L*DCS)/48.      IF (J .EQ. 1) KLM = 2      IF (J .EQ. 3) KLM = 16      UV(J,KLM) = KQ2*(-22.*DSN + 78.*KQ2*SN**2*DSN     1          + 6.*LV*CS + 6.*L*DCS)/32.      UV(J+1,KLM) = 3.*KQ2**2*(5.*DCS*SN**2 + 10.*CS*SN*DSN     1            - LV*SN - L*DSN)/16.      IF (J .EQ. 1) KLM = 3      IF (J .EQ. 3) KLM = 19      UV(J,KLM) = - KQ2*(13.*DCS*SN**2 + 26.*CS*SN*DSN     1          + 3.*LV*SN + 3.*L*DSN)/16.      UV(J+1,KLM) = KQ2*(-26.*DSN + 90.*KQ2*SN**2*DSN     1            - 6.*LV*CS - 6.*L*DCS)/32.      IF (J .EQ. 1) KLM = 4      IF (J .EQ. 3) KLM = 20      UV(J,KLM) = (- 9.*DSN - 39.*KQ2*SN**2*DSN     1          + 9.*LV*CS + 9.*L*DCS)/48.      UV(J+1,KLM) = - KQ2*(5.*DCS*SN**2 + 10.*CS*SN*DSN     1            + 3.*LV*SN + 3.*L*DSN)/16.      IF (J .EQ. 1) KLM = 8      IF (J .EQ. 3) KLM = 5      UV(J,KLM) = KQ2**2*(- 3.*DCS*SNO**2 - 6.*CS*SNO*DSNO     1          + 2.*LV*SN + 2.*L*DSN - 3.*DSN*SNO*CSO - 3.*SN*DSNO*CSO     2          - 3.*SN*SNO*DCSO)/16.      UV(J+1,KLM) = KQ2**2*(2.*LV*CS + 2.*L*DCS - 9.*DCS*CSO*SNO     1            - 9.*CS*DCSO*SNO - 9.*CS*CSO*DSNO - 9.*DSN     2            - 11.*KQ2*DSN*SNO**2 - 22.*KQ2*SN*SNO*DSNO)/16.      IF (J .EQ. 1) KLM = 14      IF (J .EQ. 3) KLM = 6      UV(J,KLM) = 3.*KQ2*(- DCS*CSO*SNO - CS*DCSO*SNO     1          - CS*CSO*DSNO + DSN - KQ2*DSN*SNO**2     2          - 2.0*KQ2*SN*SNO*DSNO)/8.      UV(J+1,KLM) = KQ2**2*(- 9.*DCS*SNO**2 - 18.*CS*SNO*DSNO     1            - 11.*DSN*SNO*CSO - 11.*SN*DSNO*CSO     2            - 11.*SN*SNO*DCSO)/8.      IF (J .EQ. 1) KLM = 17      IF (J .EQ. 3) KLM = 7      UV(J,KLM) = - KQ2*(3.*DCS*SNO**2 + 6.*CS*SNO*DSNO     1          + 2.*LV*SN + 2.*L*DSN + 3.*DSN*CSO*SNO + 3.*SN*DCSO*SNO     2          + 3.*SN*CSO*DSNO)/16.      UV(J+1,KLM) = - KQ2*(2.*LV*CS + 2.*L*DCS + 9.*DCS*CSO*SNO     1            + 9.*CS*DCSO*SNO + 9.*CS*CSO*DSNO     2            + 11.*KQ2*DSN*SNO**2 + 22.*KQ2*SN*SNO*DSNO     3            + 5.*DSN)/16.      IF (J .EQ. 1) KLM = 9      IF (J .EQ. 3) KLM = 11      UV(J,KLM) = KQ2*(3.*DCS*CSO*SNO + 3.*CS*DCSO*SNO     1          + 3.*CS*CSO*DSNO - 2.*LV*CS - 2.*L*DCS - 3.*DSN*CSO**2     2          - 6.*SN*CSO*DCSO - 6.*DSN)/16.      UV(J+1,KLM) = KQ2**2*(11.*DCS*SNO**2 + 22.*CS*SNO*DSNO     1            + 2.*LV*SN + 2.*L*DSN - 9.*DSN*CSO*SNO     2            - 9.*SN*DCSO*SNO - 9.*SN*CSO*DSNO)/16.      IF (J .EQ. 1) KLM = 15      IF (J .EQ. 3) KLM = 12      UV(J,KLM) = 3.*KQ2*(DCS*SNO**2 + 2.*CS*SNO*DSNO     1          - DSN*CSO*SNO - SN*DCSO*SNO - SN*CSO*DSNO)/8.      UV(J+1,KLM) = KQ2*(11.*DCS*CSO*SNO + 11.*CS*DCSO*SNO     1            + 11.*CS*CSO*DSNO - 3.*DSN - 9.*KQ2*DSN*SNO**2     2            - 18.*KQ2*SN*SNO*DSNO)/8.      IF (J .EQ. 1) KLM = 18      IF (J .EQ. 3) KLM = 13      UV(J,KLM) = (3.*DCS*CSO*SNO + 3.*CS*DCSO*SNO     1          + 3.*CS*CSO*DSNO + 2.*LV*CS + 2.*L*DCS - 3.*DSN*CSO**2     2          - 6.*SN*CSO*DCSO - 2.*DSN)/16.      UV(J+1,KLM) = KQ2*(11.*DCS*SNO**2 + 22.*CS*SNO*DSNO     1            - 2.*LV*SN - 2.*L*DSN - 9.*DSN*CSO*SNO     2            - 9.*SN*DCSO*SNO - 9.*SN*CSO*DSNO)/16.      UV(J,50+J) = - KQ2*(3.*LV*SN + 3.*L*DSN + 2.*L*LV*CS     1           + L**2*DCS)/8.      UV(J,51+J) = (- 2.0*KQ2*L*LV*SN - KQ2*L**2*DSN + LV*CS     1           + L*DCS - DSN)/8.      UV(J+1,50+J) = KQ2*(- 5.*LV*CS - 5.*L*DCS - 3.*DSN     1             + 2.0*KQ2*L*LV*SN + KQ2*L**2*DSN)/8.      UV(J+1,51+J) = KQ2*(-3.*LV*SN - 3.*L*DSN - 2.*L*LV*CS     1             - L**2*DCS)/8.  100 RETURN      END